package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenReducedDecimalFractionScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1",ID=DecimalToFractionSupply.ID;
 private static Question reduced(String raw){return new Question(ID,raw+"의 값을 기약분수로 나타내세요.","poison","999");}
 @Test public void normalNaSevenSupplyUsesPublicSimplestPromptAndAllThreeDisplayedPrecisions(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();assertTrue(pack.inGrade(ID,7));CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,ID,7);assertTrue(limits.variedFacts());assertTrue(limits.reducedDecimalFraction());assertEquals(0,limits.givenMinimum(1));assertEquals(3,limits.decimalPlaces(1));
  Generator gen=new Generator(new Random(359));List<String> recent=new ArrayList<>();Set<Integer> precisions=new HashSet<>();boolean actualReduction=false,coprime=false,improper=false;
  for(int i=0;i<180;i++){Question q=gen.next(ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var g=DecimalToFractionSupply.readGeneral(q);assertNotNull(g);assertTrue(g.reduced());assertTrue(q.prompt.contains("기약분수"));assertTrue(limits.allows(q));precisions.add(g.places());actualReduction|=g.gcd().compareTo(BigInteger.ONE)>0;coprime|=g.gcd().equals(BigInteger.ONE);improper|=g.value().compareTo(Rational.ONE)>0;assertEquals("fraction",q.answerFormat);assertTrue(FractionInput.defaultFraction(q));assertEquals(7,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());assertTrue(new Checker().check(q,List.of(),List.of(g.value().n+"/"+g.value().d)).correct());}
  assertEquals(Set.of(1,2,3),precisions);assertTrue(actualReduction&&coprime&&improper);
 }
 @Test public void generalFiniteNineByNineDecimalsPreserveRawZeroTrailingZerosAndImproperValues(){
  for(String raw:List.of("0.00","0.50","009.500","99.999","0.000000001","999999999.999999999")){Question q=reduced(raw);var g=DecimalToFractionSupply.readGeneral(q);assertNotNull(g);assertEquals(raw,g.raw());assertEquals(raw,DecimalToFractionSupply.read(q));assertEquals(raw.length()-raw.indexOf('.')-1,g.places());assertEquals(BigInteger.TEN.pow(g.places()),g.denominator());assertEquals(new BigDecimal(raw).unscaledValue(),g.numerator());assertEquals(g.numerator().gcd(g.denominator()),g.gcd());assertEquals(new Rational(g.numerator(),g.denominator()),g.value());assertTrue(new Checker().check(q,List.of(),List.of(g.value().n+"/"+g.value().d)).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());assertTrue(h.step(0).accepts(raw));assertTrue(h.step(2).accepts(g.denominator().toString()));assertTrue(h.step(3).accepts(g.numerator().toString()));assertTrue(h.step(4).accepts(g.gcd().toString()));assertTrue(h.step(5).accepts(g.value().n.toString()));assertTrue(h.step(6).accepts(g.value().d.toString()));}
  var zero=DecimalToFractionSupply.readGeneral(reduced("0.00"));assertEquals(BigInteger.valueOf(100),zero.gcd());assertEquals(BigInteger.ONE,zero.value().d);assertEquals(Rational.of(19,2),DecimalToFractionSupply.readGeneral(reduced("009.500")).value());assertFalse(GlobalCurriculum.limits(SYSTEM,ID,7).allows(reduced("0.000000001")));assertTrue(CurriculumLimits.NONE.allows(reduced("0.000000001")));
 }
 @Test public void publicGuideReadbackDoesNotMutatePrivateKeysAndKeepsReducedDraftAndNoTransfer(){
  Question q=reduced("0.450");q.kind="number";q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());assertFalse(h.canTransfer());List<String> a=List.of("0.450","3","1000","450","50","9","20");for(int i=0;i<7;i++){assertEquals("",h.step(i).after);assertTrue(h.step(i).accepts(a.get(i)));assertFalse(h.step(i).accepts(""));}assertFalse(h.step(4).accepts("5"));HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.teachingVersion="decimal-reduced-fraction-v1";d.stage=7;d.entries=new ArrayList<>(a);HelpPlan.Draft restored=h.restore(d.copy(),q.id);assertEquals(7,restored.stage);assertEquals(a,restored.entries.subList(0,7));assertEquals("9/20",h.enteredAnswer(restored));assertSame(stored,q.studyGuide);assertEquals("999",stored.frames.get(0).expected);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);
 }
 @Test public void relatedReferencesUseOnlyCorrectLearnerEntriesWithoutComputedReductionPrefill(){
  Question q=reduced("0.450");List<String> entries=new ArrayList<>(List.of("0.450","3","1000","450","50","9","20"));assertEquals(Map.of(),DecimalToFractionSupply.references(q,4,List.of()));assertEquals(Map.of("소수점 아래 자릿수 p = ","3"),DecimalToFractionSupply.references(q,2,entries));assertEquals(Map.of("소수 v = ","0.450","분모 d = ","1000"),DecimalToFractionSupply.references(q,3,entries));assertEquals(Map.of("분자 n = ","450","최대공약수 g = ","50"),DecimalToFractionSupply.references(q,5,entries));assertEquals(Map.of("분모 d = ","1000","최대공약수 g = ","50"),DecimalToFractionSupply.references(q,6,entries));assertFalse(DecimalToFractionSupply.references(q,5,entries).containsValue("9"));entries.set(4,"5");assertEquals(Map.of("분자 n = ","450"),DecimalToFractionSupply.references(q,5,entries));assertEquals(Map.of(),DecimalToFractionSupply.references(q,7,entries));
 }
 @Test public void explicitReductionAndLegacyEquivalentFormatContractsRemainDifferent(){
  Question q=reduced("0.45");q.kind="number";q.answerFormat="fraction";Checker check=new Checker();assertTrue(check.check(q,List.of(),List.of("9/20")).correct());assertEquals("약분 필요",check.check(q,List.of(),List.of("45/100")).message);assertEquals(Checker.Status.WRONG_ANSWER,check.check(q,List.of(),List.of("9/21")).status);assertEquals(Checker.Status.INPUT_NEEDED,check.check(q,List.of(),List.of("0.45")).status);assertEquals(1,DecimalToFractionSupply.errorPart(q,"10/20"));assertEquals(2,DecimalToFractionSupply.errorPart(q,"9/21"));assertEquals(0,DecimalToFractionSupply.errorPart(q,"45/100"));
  Question old=DecimalToFractionSupply.make(0,45,2);assertTrue(check.check(old,List.of(),List.of("45/100")).correct());HelpPlan plain=HelpPlan.forQuestion(old);assertEquals(4,plain.size());assertFalse(plain.canTransfer());HelpPlan.Draft saved=new HelpPlan.Draft();saved.questionId=old.id;saved.teachingVersion="decimal-fraction-relations-v1";saved.stage=4;saved.entries=new ArrayList<>(List.of("0.45","2","100","45"));HelpPlan.Draft restored=plain.restore(saved,old.id);assertEquals(4,restored.stage);assertEquals("45/100",plain.enteredAnswer(restored));
  for(String input:List.of("9/0","1e2","9+0/20","1".repeat(241),"1".repeat(31)+"/20"))assertFalse(input,check.check(q,List.of(),List.of(input)).correct());
 }
 @Test public void invalidPublicReturnsNullWithoutStoredFallbackAndSelectedBoundsUseOnlyPublicData(){
  for(String raw:List.of("0.(3)","0.333…","1e-3","-0.45",".45","0,45","0.1234567890","1234567890.0")){Question q=reduced(raw);q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;assertNull(DecimalToFractionSupply.readGeneral(q));assertNull(DecimalToFractionSupply.read(q));assertNull(DecimalToFractionSupply.guide(q));assertNull(HelpPlan.forQuestion(q));assertSame(stored,q.studyGuide);assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("999")).status);}
  Question q=reduced("0.450");q.expression="-999.999999999";q.answers=new String[]{"-999"};CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,ID,7);assertTrue(limits.allows(q));q.expression=null;q.answers=null;assertTrue(limits.allows(q));assertEquals(7,HelpPlan.forQuestion(q).size());assertNull(q.expression);assertNull(q.answers);assertFalse(new CurriculumLimits("decimalPlaces=2").allows(q));assertFalse(new CurriculumLimits("maxResult=0.4").allows(q));assertFalse(new CurriculumLimits("minGiven=1").allows(q));assertTrue(new CurriculumLimits("maxFractionValue=1;nonnegative=true;answerDecimalPlaces=3").allows(q));assertNull(DecimalToFractionSupply.guide(null));
 }
 @Test public void naSixSelectedRuleAndSevenFrameLegacySupplyRemainUnchanged(){
  CurriculumLimits six=GlobalCurriculum.limits(SYSTEM,ID,6);assertEquals(2,six.decimalPlaces(1));assertTrue(six.variedFacts());assertTrue(six.reducedDecimalFraction());Generator gen=new Generator(new Random(287));List<String> recent=new ArrayList<>();Set<Integer> precisions=new HashSet<>();for(int i=0;i<150;i++){Question q=gen.next(ID,recent,false,six);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var g=DecimalToFractionSupply.readGeneral(q);assertNotNull(g);precisions.add(g.places());assertTrue(g.reduced());assertTrue(six.allows(q));assertEquals(7,HelpPlan.forQuestion(q).size());assertTrue(new Checker().check(q,List.of(),List.of(g.value().n+"/"+g.value().d)).correct());}assertEquals(Set.of(1,2),precisions);
 }
}
